CREATE OR REPLACE FUNCTION public.get_profile_plan_badges(_ids uuid[]) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_object_agg(p.id::text,public.profile_plan_badge(p.id)) FILTER(WHERE public.profile_plan_badge(p.id) IS NOT NULL),'{}'::jsonb) FROM public.profiles p WHERE auth.uid() IS NOT NULL AND p.id=ANY(_ids[1:2000]) AND public.subscriber_can_see(auth.uid(),p.id) $$;
REVOKE ALL ON FUNCTION public.get_profile_plan_badges(uuid[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_profile_plan_badges(uuid[]) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_public_plan_badge(_slug text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.profile_plan_badge(p.id) FROM public.profiles p WHERE p.slug=_slug AND p.is_active AND p.public_profile_enabled LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.get_public_plan_badge(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.get_public_plan_badge(text) TO service_role;
-- Keep plan eligibility and commercial terms under the same lock used by reservation.
DO $$ DECLARE definition text; BEGIN definition:=pg_get_functiondef('public.reserve_asaas_contract(uuid,uuid,text)'::regprocedure); definition:=replace(definition,'contract_template_id IS NULL; IF NOT FOUND','contract_template_id IS NULL FOR UPDATE; IF NOT FOUND'); EXECUTE definition; END $$;